INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stress', 'n./v.', '/stres/', '压力;焦虑;(使)焦虑不安', 'Too much stress can make you feel sick and tired.', '压力过大会让你感到难受和疲惫。', 'Fighting Stress', 1, 0, 'senior', 'wordlist', 'elective3', 'U1', 'deal with stress', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anxiety', 'n.', '/æŋˈzaɪəti/', '焦虑;担忧;忧虑', 'The thought of the exam filled her with anxiety.', '一想到考试,她就充满了焦虑。', 'Fighting Stress', 2, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel anxiety', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'anxious', 'adj.', '/ˈæŋkʃəs/', '焦虑的;担心的;渴望的', 'Many teenagers feel anxious about tests and homework.', '许多青少年对考试和作业感到焦虑。', 'Fighting Stress', 3, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel anxious about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frustrated', 'adj.', '/frʌˈstreɪtɪd/', '沮丧的;懊恼的;失望的', 'He felt frustrated when he could not solve the problem.', '解决不了这个问题,他感到很沮丧。', 'Fighting Stress', 4, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel frustrated', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'scared', 'adj.', '/skeəd/', '害怕的;恐惧的;担心的', 'She was scared that something bad might happen.', '她害怕可能会有坏事发生。', 'Fighting Stress', 5, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be scared of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'nervous', 'adj.', '/ˈnɜːvəs/', '紧张的;焦虑的;神经的', 'I always feel nervous before giving a report in class.', '在课堂上做汇报前我总是很紧张。', 'Fighting Stress', 6, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel nervous', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tremendous', 'adj.', '/trɪˈmendəs/', '巨大的;极大的', 'Just thinking about it caused her tremendous worry.', '光是想想就让她极度担忧。', 'Fighting Stress', 7, 0, 'senior', 'wordlist', 'elective3', 'U1', 'tremendous pressure', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'churn', 'v.', '/tʃɜːn/', '(胃因紧张而)翻腾,反胃', 'Before the speech, his stomach began to churn with fear.', '演讲前,他的胃因恐惧而翻腾起来。', 'Fighting Stress', 8, 0, 'senior', 'wordlist', 'elective3', 'U1', 'make your stomach churn', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'swallow', 'v.', '/ˈswɒləʊ/', '吞下;咽下', 'She was so nervous that she could hardly swallow.', '她紧张得几乎咽不下东西。', 'Fighting Stress', 9, 0, 'senior', 'wordlist', 'elective3', 'U1', 'hard to swallow', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thrilling', 'adj.', '/ˈθrɪlɪŋ/', '惊险刺激的;令人兴奋的', 'My friend said that skydiving was a thrilling experience.', '我朋友说跳伞是一次惊险刺激的经历。', 'Fighting Stress', 10, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a thrilling experience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'perceive', 'v.', '/pəˈsiːv/', '察觉;理解;看待', 'Two people may perceive the same situation very differently.', '两个人对同一件事的看法可能截然不同。', 'Fighting Stress', 11, 0, 'senior', 'wordlist', 'elective3', 'U1', 'perceive a situation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'physically', 'adv.', '/ˈfɪzɪkli/', '身体上;在体格上', 'Worry in your mind can make you physically feel bad.', '内心的担忧会让你身体上感到不适。', 'Fighting Stress', 12, 0, 'senior', 'wordlist', 'elective3', 'U1', 'physically tired', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sweaty', 'adj.', '/ˈsweti/', '出汗的;汗津津的', 'Before the test, my hands felt cold and sweaty.', '考试前,我的手又冷又出汗。', 'Fighting Stress', 13, 0, 'senior', 'wordlist', 'elective3', 'U1', 'sweaty hands', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'inspire', 'v.', '/ɪnˈspaɪə(r)/', '激励;鼓舞;启发', 'A little anxiety may inspire you to prepare well.', '一点点焦虑也许会激励你做好准备。', 'Fighting Stress', 14, 0, 'senior', 'wordlist', 'elective3', 'U1', 'inspire sb to do', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bother', 'v.', '/ˈbɒðə(r)/', '使烦恼;打扰;费心', 'Talk to an adult about what is bothering you.', '把困扰你的事情告诉一位大人。', 'Fighting Stress', 15, 0, 'senior', 'wordlist', 'elective3', 'U1', 'what is bothering you', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'leisure', 'n.', '/ˈleʒə(r)/', '闲暇;空闲;休闲', 'Reading books took up much of my leisure time.', '读书占去了我大部分的闲暇时间。', 'Fighting Stress', 16, 0, 'senior', 'wordlist', 'elective3', 'U1', 'leisure time', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'handle', 'v.', '/ˈhændl/', '应对;处理;对付', 'Getting enough sleep helps you handle stress better.', '充足的睡眠能帮你更好地应对压力。', 'Fighting Stress', 17, 0, 'senior', 'wordlist', 'elective3', 'U1', 'handle stress', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'obvious', 'adj.', '/ˈɒbviəs/', '明显的;显而易见的', 'If there is no obvious reason for your fear, the anxiety may be too high.', '如果恐惧没有明显的原因,焦虑可能就过头了。', 'Fighting Stress', 18, 0, 'senior', 'wordlist', 'elective3', 'U1', 'an obvious reason', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'continually', 'adv.', '/kənˈtɪnjuəli/', '不断地;一再地;频繁地', 'Continually checking the same thing is a sign of too much worry.', '反复检查同一件事是过度担忧的表现。', 'Fighting Stress', 19, 0, 'senior', 'wordlist', 'elective3', 'U1', 'continually check', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'panicky', 'adj.', '/ˈpænɪki/', '惊慌的;焦虑不安的', 'He felt so panicky that he could not take the test calmly.', '他惊慌不已,无法平静地参加考试。', 'Fighting Stress', 20, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel panicky', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'function', 'v./n.', '/ˈfʌŋkʃn/', '起作用;正常运转;功能', 'Too much anxiety makes it hard to function in daily life.', '过度焦虑会让人难以正常应对日常生活。', 'Fighting Stress', 21, 0, 'senior', 'wordlist', 'elective3', 'U1', 'function well', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'emotion', 'n.', '/ɪˈməʊʃn/', '情感;情绪;激情', 'It is important to recognise the emotion you are feeling.', '认清自己正在经历的情绪很重要。', 'Fighting Stress', 22, 0, 'senior', 'wordlist', 'elective3', 'U1', 'control your emotion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'admit', 'v.', '/ədˈmɪt/', '承认;接纳;允许进入', 'Sometimes just admitting that you are stressed can help.', '有时仅仅承认自己有压力就会有帮助。', 'Fighting Stress', 23, 0, 'senior', 'wordlist', 'elective3', 'U1', 'admit that', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'therapist', 'n.', '/ˈθerəpɪst/', '治疗师;治疗专家', 'If the worry lasts, getting help from a therapist is wise.', '如果担忧持续不退,求助治疗师是明智之举。', 'Fighting Stress', 24, 0, 'senior', 'wordlist', 'elective3', 'U1', 'see a therapist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'negative', 'adj.', '/ˈneɡətɪv/', '消极的;负面的;否定的', 'Relaxation can help reduce negative thoughts and worry.', '放松有助于减少消极的想法和担忧。', 'Fighting Stress', 25, 0, 'senior', 'wordlist', 'elective3', 'U1', 'negative thoughts', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'meditation', 'n.', '/ˌmedɪˈteɪʃn/', '冥想;沉思;深思', 'Common relaxation techniques include deep breathing and meditation.', '常见的放松方法包括深呼吸和冥想。', 'Fighting Stress', 26, 0, 'senior', 'wordlist', 'elective3', 'U1', 'practise meditation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'yoga', 'n.', '/ˈjəʊɡə/', '瑜伽;瑜伽术', 'Doing yoga every morning helps me stay calm and relaxed.', '每天早上练瑜伽让我保持平静和放松。', 'Fighting Stress', 27, 0, 'senior', 'wordlist', 'elective3', 'U1', 'do yoga', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'vision', 'n.', '/ˈvɪʒn/', '视力;视野;眼界', 'Some people calm down by focusing their vision on one object.', '有些人通过把视线集中在一个物体上来平静下来。', 'Fighting Stress', 28, 0, 'senior', 'wordlist', 'elective3', 'U1', 'focus your vision', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'balanced', 'adj.', '/ˈbælənst/', '平衡的;均衡的', 'To have a balanced life is the best way to fight stress.', '拥有平衡的生活是应对压力的最佳方式。', 'Fighting Stress', 29, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a balanced life', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'relaxation', 'n.', '/ˌriːlækˈseɪʃn/', '放松;消遣;休息', 'You can turn to relaxation exercises to get rid of stress.', '你可以借助放松练习来摆脱压力。', 'Fighting Stress', 30, 0, 'senior', 'wordlist', 'elective3', 'U1', 'relaxation exercises', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'breathe', 'v.', '/briːð/', '呼吸', 'Breathe in slowly through your nose and then breathe out.', '用鼻子慢慢吸气,然后再呼气。', 'Fighting Stress', 31, 0, 'senior', 'wordlist', 'elective3', 'U1', 'breathe deeply', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'recognise', 'v.', '/ˈrekəɡnaɪz/', '认识到;认出;承认', 'Once you recognise that you are stressed, you can act.', '一旦意识到自己有压力,你就能采取行动。', 'Fighting Stress', 32, 0, 'senior', 'wordlist', 'elective3', 'U1', 'recognise the signs', '美式拼 recognize;美音 /ˈrekəɡnaɪz/', 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cope', 'v.', '/kəʊp/', '(成功地)应对,处理', 'Many teens find healthy ways to cope with anxiety.', '许多青少年找到了应对焦虑的健康方式。', 'Fighting Stress', 33, 0, 'senior', 'wordlist', 'elective3', 'U1', 'cope with anxiety', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'upset', 'adj.', '/ʌpˈset/', '心烦的;难过的;不安的', 'Going through hard times every day can make you upset.', '每天都经历难事会让你心烦意乱。', 'Fighting Stress', 34, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel upset', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'overwhelmed', 'adj.', '/ˌəʊvəˈwelmd/', '不知所措的;难以承受的', 'Students often feel overwhelmed when they have too much homework.', '作业太多时,学生常常感到不知所措。', 'Fighting Stress', 35, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel overwhelmed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'calm', 'adj./v.', '/kɑːm/', '平静的;镇定的;使平静', 'Deep breathing can help you stay calm before a big test.', '深呼吸能帮你在大考前保持平静。', 'Fighting Stress', 36, 0, 'senior', 'wordlist', 'elective3', 'U1', 'stay calm', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'composed', 'adj.', '/kəmˈpəʊzd/', '镇定的;沉着的', 'Knowing how to relax helps me stay composed under pressure.', '懂得放松让我在压力下保持沉着。', 'Fighting Stress', 37, 0, 'senior', 'wordlist', 'elective3', 'U1', 'stay composed', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frightened', 'adj.', '/ˈfraɪtnd/', '害怕的;受惊的', 'When you are stressed, you may feel angry or frightened.', '有压力时,你可能感到愤怒或害怕。', 'Fighting Stress', 38, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be frightened of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'worried', 'adj.', '/ˈwʌrid/', '担心的;忧虑的', 'Stress is what you feel when you are worried about something.', '压力就是你为某事担忧时的感受。', 'Fighting Stress', 39, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be worried about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'headache', 'n.', '/ˈhedeɪk/', '头痛;令人头疼的事', 'Worrying too much sometimes gives me a terrible headache.', '过度担忧有时会让我头痛得厉害。', 'Fighting Stress', 40, 0, 'senior', 'wordlist', 'elective3', 'U1', 'get a headache', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sadness', 'n.', '/ˈsædnəs/', '悲伤;难过', 'I saw a deep sadness in the lonely boy''s eyes.', '我从那个孤独男孩的眼里看到了深深的悲伤。', 'Fighting Stress', 41, 0, 'senior', 'wordlist', 'elective3', 'U1', 'deep sadness', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stressed out', 'phrase', '/ˌstrest ˈaʊt/', '焦虑不堪;心力交瘁', 'If you leave no time to play, you can get stressed out.', '如果不留点玩的时间,你会变得焦虑不堪。', 'Fighting Stress', 42, 0, 'senior', 'wordlist', 'elective3', 'U1', 'get stressed out', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'get rid of', 'phrase', '/ˌɡet ˈrɪd əv/', '摆脱;去除;丢弃', 'Relaxation exercises can help you get rid of stress.', '放松练习能帮你摆脱压力。', 'Fighting Stress', 43, 0, 'senior', 'wordlist', 'elective3', 'U1', 'get rid of stress', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'take care of', 'phrase', '/ˌteɪk ˈkeər əv/', '照顾;照料;处理', 'If you take care of yourself, you will be less stressed.', '如果照顾好自己,你就不会那么有压力。', 'Fighting Stress', 44, 0, 'senior', 'wordlist', 'elective3', 'U1', 'take care of yourself', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'turn to', 'phrase', '/ˈtɜːn tə/', '求助于;转向', 'When you feel low, you can turn to a parent you trust.', '情绪低落时,你可以求助于你信任的父母。', 'Fighting Stress', 45, 0, 'senior', 'wordlist', 'elective3', 'U1', 'turn to an adult', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bring up', 'phrase', '/ˌbrɪŋ ˈʌp/', '提出(讨论等);抚养', 'Bring up what has been on your mind with a teacher.', '把你心里挂念的事向老师提出来。', 'Fighting Stress', 46, 0, 'senior', 'wordlist', 'elective3', 'U1', 'bring up a worry', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'out of the ordinary', 'phrase', '/ˌaʊt əv ðə ˈɔːdnri/', '不寻常的;特别的', 'Worrying about things that are out of the ordinary may signal high anxiety.', '为不寻常的事担忧可能是焦虑过高的信号。', 'Fighting Stress', 47, 0, 'senior', 'wordlist', 'elective3', 'U1', 'nothing out of the ordinary', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'state of mind', 'phrase', '/ˌsteɪt əv ˈmaɪnd/', '心境;心理状态', 'Singing softly can help you reach a calmer state of mind.', '轻声哼唱能帮你达到更平静的心境。', 'Fighting Stress', 48, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a calm state of mind', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u1.01', '①不定式作主语(To do ... is/takes ...)', 'A2', 12, '上外版选择性必修第三册 U1 — 句首主语位置不能放有限动词;表达''做某事''作主语时用不定式 To do(如 To have a balanced life is the best way to fight stress)。', 1, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u1.02', '②it 作形式主语 + 真正主语不定式(It is ... to do ...)', 'A2', 12, '上外版选择性必修第三册 U1 — 为了句子平衡,常用 it 作形式主语,把真正主语不定式放句尾:It is important to stay calm。形式主语只能用 it;句尾真正主语用 to do。', 2, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se3u1.03', '③不定式作表语(主语 + be + to do ...)', 'A2', 12, '上外版选择性必修第三册 U1 — 系动词 be 后用不定式作表语,说明、解释或等同主语:My plan is to do some volunteer work;The best way to relax is to breathe slowly。', 3, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ a balanced life is the best way to fight stress."', 'To have', 'Have', 'Has', 'Had', 'A', '句首主语位置不能用有限动词;''拥有平衡生活''作主语 → 不定式 To have。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ enough sleep every night helps you handle stress."', 'Get', 'To get', 'Gets', 'Got', 'B', '主语位置用不定式 To get,有限动词 get/gets/got 不能作主语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ too much homework at once can make you anxious."', 'Face', 'Faces', 'To face', 'Faced', 'C', '''面对''作主语 → To face;其余为有限动词形式。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ slowly and deeply is a simple way to calm down."', 'Breathe', 'Breathes', 'Breathed', 'To breathe', 'D', '主语为''缓慢深呼吸''→ 不定式 To breathe。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ about your worries with a friend often helps."', 'To talk', 'Talk', 'Talks', 'Talked', 'A', '''谈论''作主语 → To talk。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ healthy food is one great way to reduce stress."', 'Eat', 'To eat', 'Eats', 'Ate', 'B', '主语位置用 To eat,不能用有限动词。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ time for fun keeps your mind fresh and calm."', 'Leave', 'Leaves', 'To leave', 'Left', 'C', '''留出时间''作主语 → To leave。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ regular exercise can lift your mood very quickly."', 'Do', 'Does', 'Did', 'To do', 'D', '主语为''做运动''→ To do。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ that you feel stressed is the first useful step."', 'To admit', 'Admit', 'Admits', 'Admitted', 'A', '''承认……''作主语 → To admit。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ your problems will never make them disappear."', 'Ignore', 'To ignore', 'Ignores', 'Ignored', 'B', '主语为''忽视''→ To ignore。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ a trusted adult for advice is always a good idea."', 'Ask', 'Asks', 'To ask', 'Asked', 'C', '''询问''作主语 → To ask。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ soft music after class helps many students relax."', 'Play', 'Plays', 'Played', 'To play', 'D', '主语位置用不定式 To play。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ the early signs of stress can save you trouble."', 'To notice', 'Notice', 'Notices', 'Noticed', 'A', '''注意到''作主语 → To notice。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ for a short walk often clears my busy mind."', 'Go', 'To go', 'Goes', 'Went', 'B', '主语为''去散步''→ To go,有限动词不能作主语。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ a journal every evening helps me feel calmer."', 'Keep', 'Keeps', 'To keep', 'Kept', 'C', '''记日记''作主语 → To keep。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ kind to yourself really matters when life gets hard."', 'Be', 'Is', 'Was', 'To be', 'D', '主语位置用不定式 To be。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ your feelings inside often makes the stress worse."', 'To hide', 'Hide', 'Hides', 'Hid', 'A', '''藏起''作主语 → To hide。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ a few breaks during study time can reduce stress."', 'Take', 'To take', 'Takes', 'Took', 'B', '主语为''休息几次''→ To take。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ a pet for a while can make you feel relaxed."', 'Hold', 'Holds', 'To hold', 'Held', 'C', '''抱一会儿宠物''作主语 → To hold。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.01'), '"____ what is bothering you is better than staying silent."', 'Share', 'Shares', 'Shared', 'To share', 'D', '主语为''说出''→ To share。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is important to stay calm before a big test."', 'It', 'That', 'There', 'This', 'A', '形式主语只能用 it,真正主语是句尾的 to stay。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is necessary to share your feelings with others."', 'There', 'It', 'That', 'This', 'B', 'it 作形式主语指代后面的 to share。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is helpful to recognise the real causes of your stress."', 'There', 'That', 'It', 'This', 'C', '形式主语用 it,后接真正主语 to recognise。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ takes courage to admit that you feel stressed."', 'There', 'That', 'This', 'It', 'D', 'It takes courage to do 固定结构,it 为形式主语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is normal to feel nervous before a performance."', 'It', 'That', 'There', 'This', 'A', '形式主语 it + 真正主语 to feel。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is hard to open up about your deepest worries."', 'There', 'It', 'That', 'This', 'B', 'it 作形式主语,真正主语为 to open up。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is wise to turn to an adult you really trust."', 'There', 'That', 'It', 'This', 'C', '形式主语用 it,后接 to turn。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ feels good to talk about what is bothering you."', 'There', 'That', 'This', 'It', 'D', 'it 作形式主语,真正主语 to talk 放句尾。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is better to face a problem than to run from it."', 'It', 'There', 'That', 'This', 'A', '形式主语 it 指代 to face。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"____ is worth taking some time to relax every single day."', 'There', 'It', 'That', 'This', 'B', 'It is worth doing 中 it 为形式主语。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is wise ____ help when your worries last too long."', 'seek', 'seeks', 'to seek', 'sought', 'C', '真正主语用不定式 to seek,放在形式主语 it 之后。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is important ____ enough sleep during exam week."', 'get', 'gets', 'got', 'to get', 'D', '句尾真正主语用 to get。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is healthy ____ some exercise several times a week."', 'to do', 'do', 'does', 'did', 'A', '真正主语为 to do,有限动词不可用。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is useful ____ a few short breaks while studying."', 'take', 'to take', 'takes', 'took', 'B', '形式主语 it 后的真正主语用 to take。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is not easy ____ calm when everything goes wrong."', 'stay', 'stays', 'to stay', 'stayed', 'C', '真正主语用不定式 to stay。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is helpful ____ slowly and deeply when you panic."', 'breathe', 'breathes', 'breathed', 'to breathe', 'D', '句尾真正主语为 to breathe。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is brave ____ that you sometimes need a little help."', 'to admit', 'admit', 'admits', 'admitted', 'A', '真正主语用 to admit。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is relaxing ____ to soft music after a long day."', 'listen', 'to listen', 'listens', 'listened', 'B', '形式主语 it 后真正主语用 to listen。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is smart ____ time for both study and play."', 'leave', 'leaves', 'to leave', 'left', 'C', '句尾真正主语为 to leave。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.02'), '"It is good ____ your worries with someone you trust."', 'share', 'shares', 'shared', 'to share', 'D', '真正主语用不定式 to share。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"John''s plan is ____ some volunteer work this weekend."', 'to do', 'does', 'did', 'done', 'A', 'be 后作表语,说明 plan 的内容 → 不定式 to do。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The best way to relax is ____ slowly and deeply."', 'breathes', 'to breathe', 'breathe', 'breathed', 'B', '系动词 is 后用不定式作表语 to breathe。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"Her main goal is ____ those in trouble find a calmer mind."', 'helps', 'helped', 'to help', 'help', 'C', '表语用不定式 to help,说明 goal 的内容。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"My favourite way to unwind is ____ a long evening walk."', 'takes', 'took', 'taken', 'to take', 'D', 'be 后作表语 → to take。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The very first step is ____ that you are feeling stressed."', 'to admit', 'admits', 'admitted', 'admit', 'A', '系动词后表语用不定式 to admit。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"Our top priority is ____ the safety of every student."', 'ensures', 'to ensure', 'ensured', 'ensure', 'B', '表语用 to ensure,等同并说明 priority。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"His new habit is ____ to calm music before going to bed."', 'listens', 'listened', 'to listen', 'listen', 'C', 'be 后作表语 → to listen。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The aim of the club is ____ teens deal with daily stress."', 'supports', 'supported', 'support', 'to support', 'D', '表语用不定式 to support。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"A wise choice is ____ enough sleep during exam week."', 'to get', 'gets', 'got', 'get', 'A', '系动词后表语用 to get。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"What matters most is ____ a healthy, balanced life."', 'lives', 'to live', 'lived', 'live', 'B', 'be 后作表语 → to live。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The mission of the centre is ____ people who feel low."', 'comforts', 'comforted', 'to comfort', 'comfort', 'C', '表语用不定式 to comfort,说明 mission。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"Her plan for the holiday is ____ yoga and read good books."', 'practises', 'practised', 'practise', 'to practise', 'D', 'be 后作表语 → to practise。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The purpose of the talk is ____ what stress really is."', 'to explain', 'explains', 'explained', 'explain', 'A', '系动词后表语用 to explain。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"My only wish now is ____ a quiet and restful weekend."', 'enjoys', 'to enjoy', 'enjoyed', 'enjoy', 'B', 'be 后作表语 → to enjoy。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The best advice is ____ what worries you with a friend."', 'shares', 'shared', 'to share', 'share', 'C', '表语用不定式 to share。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"One good idea is ____ for a run whenever you feel tense."', 'goes', 'went', 'gone', 'to go', 'D', 'be 后作表语 → to go。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The key to a calm mind is ____ time for rest and fun."', 'to leave', 'leaves', 'left', 'leave', 'A', '系动词后表语用 to leave。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"His main goal this term is ____ stress from taking over."', 'keeps', 'to keep', 'kept', 'keep', 'B', '表语用不定式 to keep。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"A simple trick is ____ on one object until you feel calm."', 'focuses', 'focused', 'to focus', 'focus', 'C', 'be 后作表语 → to focus。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective3' AND unit='U1' AND code='se3u1.03'), '"The best response to worry is ____ it instead of hiding it."', 'faces', 'faced', 'face', 'to face', 'D', '系动词后表语用不定式 to face。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'What Is Stress?', 'Stress is what you feel when you are worried or uncomfortable about something. This worry in your mind can make you physically feel bad. You may feel angry, frightened or upset, and that feeling can give you a headache or an upset stomach. When you are stressed, you may not want to sleep or eat, or you may do too much of both. Plenty of things can cause it, and there is such a thing as good stress and bad stress. Good stress may show up when you are called on in class or have to give a report. A little of it can even inspire you to prepare well. But bad stress happens when the worried feelings last for a long time, perhaps because someone in your family is ill or you have problems at school every day. That kind of stress will not help you. In fact, if it goes on and on, it can actually make you sick.', '说明·什么是压力', 161, '[{"q":"According to the text, what is stress?","answer":"A","options":["A feeling that comes when something worries or troubles you.","A kind of illness that doctors must treat.","A type of food that is bad for you.","A game that teenagers like to play."],"explanation":"首句把压力定义为''担忧或不舒服时的感受''的转述。"},{"q":"What can good stress do for you?","answer":"B","options":["It makes you sleep all day.","It can push you to get ready well.","It always makes you sick at once.","It removes every kind of worry."],"explanation":"''A little of it can even inspire you to prepare well'' 的转述。"},{"q":"When does stress become bad for you?","answer":"A","options":["When the worried feelings go on for a long time.","When it lasts only a few minutes.","When it happens before a fun trip.","When a teacher calls on you in class."],"explanation":"原文指出坏压力是担忧感持续很久时出现的,选项为其转述。"}]'::jsonb, '[{"word":"stress","cn":"压力"},{"word":"frightened","cn":"害怕的"},{"word":"inspire","cn":"激励"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'How Your Body Reacts', 'Have you ever had butterflies in your stomach or sweaty hands before a big test? These are signs that your body is reacting to stress. When you feel worried, your heart may beat faster, your stomach may churn, and your knees may feel weak. Some people even feel a lump in their throat when they try to swallow. These reactions are not strange at all. Long ago, when people lived in the wild, this quick response helped them stay alert and react to danger fast. The same system still switches on today, even though our worries are usually about tests, friends or homework rather than wild animals. A small amount of this response is useful, because it keeps you awake and focused. The problem comes when the feeling is too strong or lasts too long. Then you may find it hard to pay attention in class or to remember things at home. Knowing why your body acts this way can make the feeling much less frightening.', '说明·身体的压力反应', 166, '[{"q":"What are sweaty hands and butterflies in the stomach examples of?","answer":"B","options":["Signs that you are seriously ill.","Clues that your body is responding to stress.","Signs that you have eaten too much.","Signs that you are very happy."],"explanation":"原文说这些是身体对压力作出反应的信号,选项为其转述。"},{"q":"Why did this quick response help people long ago?","answer":"C","options":["It helped them sleep more deeply.","It helped them eat less food.","It kept them alert so they could meet danger quickly.","It helped them avoid all worry."],"explanation":"原文''helped them stay alert and react to danger fast''的转述。"},{"q":"What does the writer say can make the feeling less frightening?","answer":"D","options":["Eating before every test.","Never taking any tests.","Keeping the worry a secret.","Understanding why the body reacts this way."],"explanation":"末句指出了解身体为何如此反应能减轻恐惧,选项为其转述。"}]'::jsonb, '[{"word":"churn","cn":"翻腾"},{"word":"swallow","cn":"吞咽"},{"word":"alert","cn":"警觉的"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Keep Your SELF in Mind', 'To have a balanced life is the best way to avoid stress. That means making good choices about how you spend your time. If you only deal with school work and leave no time to play, you can easily get stressed out. A simple way to remember what matters is to keep your SELF in mind. The letters stand for Sleep, Exercise, Leisure and Food. Getting enough sleep and eating healthy food are two great ways to handle daily pressure. Exercise lifts your mood and clears your busy mind, while leisure gives you a chance to enjoy the things you love. None of these four things should be missing for long. When students forget to rest or never make time for fun, small worries can grow into big ones. So make a plan that includes all four parts of your SELF. If you take care of yourself in this way and still leave room for the people around you, you will probably feel calmer and far less stressed.', '说明·平衡生活的四件事', 168, '[{"q":"What does the writer say is the best way to avoid stress?","answer":"A","options":["Living a life that is well balanced.","Studying as many hours as possible.","Giving up all of your hobbies.","Sleeping through the whole weekend."],"explanation":"首句''To have a balanced life is the best way to avoid stress''的转述。"},{"q":"What do the four letters of SELF stand for?","answer":"B","options":["Study, Energy, Love and Fun.","Sleep, Food, Exercise and Leisure.","Speed, Effort, Luck and Faith.","School, Email, Lunch and Friends."],"explanation":"原文给出 SELF = Sleep、Exercise、Leisure、Food 四件事,正确项含全部四词。"},{"q":"What may happen if students never make time for fun?","answer":"C","options":["They will sleep far too little.","They will become star athletes.","Minor worries may slowly turn into serious ones.","They will forget how to study."],"explanation":"原文指出忘记休息或不留娱乐时间会让小烦恼变大,选项为其转述。"}]'::jsonb, '[{"word":"balanced","cn":"平衡的"},{"word":"leisure","cn":"闲暇"},{"word":"handle","cn":"应对"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'When Anxiety Is Too Much', 'All teens feel anxious from time to time, but some feel it far more than others. A certain amount of worry is normal, especially before a test or a date. So how much anxiety is too much? Here are a few warning signs. You may feel afraid for no clear reason at all, even when nothing bad is happening. You may worry so much about ordinary events that you start to avoid them. You may check the same thing again and again, long after you know it is right. You may also feel so panicky that you cannot take a test or talk to friends. If these signs sound familiar, your anxiety level may be too high. The good news is that there are healthy ways to cope. It helps to recognise the kinds of situations that make you anxious and to admit that they are hard. Sometimes simply being ready for a difficult moment makes it easier. If these steps are not enough, getting help from a doctor or therapist is a wise next move.', '说明·过度焦虑的信号', 176, '[{"q":"What does the writer say about feeling some worry before a test?","answer":"D","options":["It is always a serious problem.","It means you should see a doctor.","It never happens to teenagers.","It is completely normal."],"explanation":"原文说考试或约会前有一定担忧是正常的,选项为其转述。"},{"q":"Which of these is named as a sign of too much anxiety?","answer":"A","options":["Checking the same thing over and over.","Sleeping well every night.","Enjoying time with friends.","Feeling calm before a date."],"explanation":"原文''check the same thing again and again''是过度焦虑的信号之一,选项为其转述。"},{"q":"What does the writer suggest doing if simple steps are not enough?","answer":"B","options":["Giving up on every activity.","Asking a doctor or therapist for help.","Hiding the problem from everyone.","Worrying even more about it."],"explanation":"末句指出若这些步骤不够,应向医生或治疗师求助,选项为其转述。"}]'::jsonb, '[{"word":"anxious","cn":"焦虑的"},{"word":"panicky","cn":"惊慌的"},{"word":"therapist","cn":"治疗师"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Simple Ways to Relax', 'When stress builds up, relaxation can help reduce worry and negative thoughts. The good news is that you do not need special tools or a lot of time. The easiest method is deep breathing. Breathe in slowly through your nose, hold the air for a moment, and then breathe out slowly through your mouth. You can do this anywhere, and no one will even notice. Many people also enjoy quiet activities such as meditation, listening to calming music or doing gentle yoga. Some find that singing softly, or even focusing their vision on a single object, helps them reach a calmer state of mind. In China, many people practise Taijiquan, an ancient form of exercise with slow, careful movements. Because it asks for a high level of attention, the busy mind slows down and a deep calm can take its place. You do not have to try all of these at once. Choose one that feels right for you, practise it often, and stress will trouble you far less.', '说明·实用的放松方法', 169, '[{"q":"What does the writer say is the easiest way to relax?","answer":"C","options":["Running for several hours.","Buying expensive equipment.","Breathing deeply and slowly.","Eating a large meal."],"explanation":"原文''The easiest method is deep breathing''的转述。"},{"q":"Why does Taijiquan help the mind become calm?","answer":"D","options":["Because it is done very quickly.","Because it requires no thinking at all.","Because it must be done in a group.","Because it calls for very careful, full attention."],"explanation":"原文说太极拳需要高度专注,因而心绪平静,选项为其转述。"},{"q":"What advice does the writer give at the end?","answer":"A","options":["Pick one method and practise it often.","Try every method on the same day.","Avoid relaxing until you are very ill.","Stop exercising completely."],"explanation":"末句建议选一种适合自己的方法常练,选项为其转述。"}]'::jsonb, '[{"word":"relaxation","cn":"放松"},{"word":"meditation","cn":"冥想"},{"word":"vision","cn":"视野"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Talking It Out', 'For a whole month, Daniel felt stressed out but told no one. He had too much homework, a test every week, and a quarrel with a close friend. Each night he lay awake, his stomach churning with worry. One afternoon his art teacher noticed how tired and upset he looked and gently asked what was bothering him. At first Daniel did not want to talk, but slowly he brought up everything that had been on his mind. To his surprise, simply saying the words out loud made the load feel lighter. His teacher did not solve every problem, yet she helped him see that he was not alone. She also showed him a quiet way to relax: drawing whatever he felt on a blank page. Art, she explained, can be a release for heavy thoughts and bring a little light into a dark mood. That evening Daniel slept well for the first time in weeks. He learned that to share a worry with someone you trust is often the first step towards feeling calm again.', '记叙·向信任的人倾诉', 175, '[{"q":"Why could Daniel not sleep at night?","answer":"B","options":["Because his room was too cold.","Because he was worried about several problems.","Because he drank too much coffee.","Because he had no homework to do."],"explanation":"原文说他因作业、考试和与朋友争吵而忧心难眠,选项为其转述。"},{"q":"How did Daniel feel after talking to his teacher?","answer":"C","options":["More tired than before.","Angry that she had asked.","As if his worries felt lighter.","Sure that nothing could help."],"explanation":"原文''made the load feel lighter''的转述。"},{"q":"What did Daniel learn from the experience?","answer":"D","options":["That he should keep every worry secret.","That teachers cannot help students.","That drawing is a waste of time.","That telling a trusted person about a worry helps."],"explanation":"末句指出向信任的人倾诉是重获平静的第一步,选项为其转述。"}]'::jsonb, '[{"word":"bother","cn":"困扰"},{"word":"release","cn":"释放"},{"word":"trust","cn":"信任"}]'::jsonb, 2, 'elective3', 'U1', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'A Stress Journal', 'Last term I often felt (1)____ and could not sleep well at night. My teacher suggested that I keep a stress (2)____. Every evening I (3)____ down what had worried me that day and how it made me (4)____. At first it felt strange, but slowly I began to (5)____ a pattern. Most of my worries came from leaving my homework until the (6)____ minute. Once I could (7)____ the real cause, it was much easier to (8)____ the problem. Writing also helped me get (9)____ of the heavy feelings inside. Now my journal is a quiet place where I can (10)____ calm again.', 104, 2, '[{"q":"1","answer":"A","options":["anxious","proud","lucky","polite"],"explanation":"felt anxious 感到焦虑,与失眠相符。"},{"q":"2","answer":"B","options":["machine","journal","ticket","garden"],"explanation":"keep a journal 记日记。"},{"q":"3","answer":"C","options":["sold","threw","wrote","ate"],"explanation":"wrote down 写下。"},{"q":"4","answer":"D","options":["sell","drive","buy","feel"],"explanation":"made me feel 让我感到。"},{"q":"5","answer":"A","options":["notice","throw","sell","lose"],"explanation":"notice a pattern 注意到规律。"},{"q":"6","answer":"B","options":["rich","last","kind","loud"],"explanation":"the last minute 最后一刻。"},{"q":"7","answer":"C","options":["forget","waste","recognise","hide"],"explanation":"recognise the cause 认清原因。"},{"q":"8","answer":"D","options":["lose","sell","break","handle"],"explanation":"handle the problem 处理问题。"},{"q":"9","answer":"A","options":["rid","out","off","down"],"explanation":"get rid of 摆脱。"},{"q":"10","answer":"B","options":["sell","find","throw","lose"],"explanation":"find calm 重获平静。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Helping a Friend', 'My best friend Lucy has been very (1)____ lately. Before every test her hands turn cold and (2)____, and her stomach seems to (3)____. I really wanted to help, so I asked her gently what was (4)____ her. She was glad that someone had finally (5)____ it up. We made a simple (6)____ together: each day she would get more (7)____, eat better food, and leave some time to (8)____. I also told her to (9)____ to a teacher if the worry ever grew too strong. Little by little, Lucy became calmer and more (10)____. Helping her made me feel good too.', 102, 2, '[{"q":"1","answer":"C","options":["rich","polite","tense","proud"],"explanation":"very tense 非常紧张。"},{"q":"2","answer":"D","options":["sunny","sleepy","sandy","sweaty"],"explanation":"cold and sweaty 又冷又出汗。"},{"q":"3","answer":"A","options":["churn","sing","shop","sleep"],"explanation":"stomach churns 胃翻腾。"},{"q":"4","answer":"B","options":["washing","bothering","painting","buying"],"explanation":"what was bothering her 困扰她的事。"},{"q":"5","answer":"C","options":["thrown","sold","brought","washed"],"explanation":"brought it up 把它说出来。"},{"q":"6","answer":"D","options":["price","noise","coin","plan"],"explanation":"a simple plan 一个简单的计划。"},{"q":"7","answer":"A","options":["sleep","money","noise","traffic"],"explanation":"get more sleep 多睡觉。"},{"q":"8","answer":"B","options":["sell","relax","argue","worry"],"explanation":"time to relax 放松的时间。"},{"q":"9","answer":"C","options":["throw","sell","turn","lose"],"explanation":"turn to a teacher 求助老师。"},{"q":"10","answer":"D","options":["angry","afraid","tired","composed"],"explanation":"calmer and more composed 更镇定。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Exam Week', 'During exam week, I was so (1)____ with revision that I could hardly sleep. There was always a lot on my (2)____. One night I ended up with a terrible (3)____ and could not study at all. My mother saw how (4)____ I looked and sat down beside me. She reminded me that a little stress is (5)____ and can even help me focus. The important thing, she said, was not to let it (6)____ too long. Together we made a timetable that left time to (7)____ and rest. After that I began to (8)____ slowly and deeply whenever I felt panicky. By the end of the week, I felt far more (9)____. I learned that the right (10)____ to stress can change everything.', 124, 2, '[{"q":"1","answer":"A","options":["busy","rich","kind","loud"],"explanation":"busy with revision 忙于复习。"},{"q":"2","answer":"B","options":["shoe","mind","table","road"],"explanation":"on my mind 挂在心上。"},{"q":"3","answer":"C","options":["holiday","garden","headache","ticket"],"explanation":"a terrible headache 严重的头痛。"},{"q":"4","answer":"D","options":["happy","proud","lucky","tired"],"explanation":"how tired I looked 我看起来多疲惫。"},{"q":"5","answer":"A","options":["normal","deadly","silent","golden"],"explanation":"stress is normal 压力是正常的。"},{"q":"6","answer":"B","options":["sell","last","sing","cook"],"explanation":"let it last 让它持续。"},{"q":"7","answer":"C","options":["argue","worry","relax","panic"],"explanation":"time to relax and rest 放松与休息。"},{"q":"8","answer":"D","options":["shout","run","jump","breathe"],"explanation":"breathe slowly and deeply 缓慢深呼吸。"},{"q":"9","answer":"A","options":["relaxed","afraid","angry","bored"],"explanation":"far more relaxed 放松得多。"},{"q":"10","answer":"B","options":["price","response","noise","coin"],"explanation":"the right response to stress 对压力的正确回应。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'A Run in the Park', 'Whenever I feel (1)____ out, I put on my shoes and go for a run in the park. Running takes my (2)____ off my problems and clears my head. As my feet hit the path, my worries seem to (3)____ away. The fresh air and green trees help me feel (4)____ again. Exercise is one of the best ways to (5)____ stress, because it lifts your mood almost at (6)____. After twenty minutes, my heart beats fast, but my mind feels (7)____. I come home pleasantly tired and able to (8)____ on my homework. That night I always sleep more (9)____. A short run cannot solve every problem, but it gives me the (10)____ to face them.', 117, 2, '[{"q":"1","answer":"C","options":["rich","polite","stressed","late"],"explanation":"stressed out 焦虑不堪。"},{"q":"2","answer":"D","options":["coat","lunch","key","mind"],"explanation":"take my mind off 让我不去想。"},{"q":"3","answer":"A","options":["fade","cook","shout","paint"],"explanation":"fade away 渐渐消退。"},{"q":"4","answer":"B","options":["angry","calm","sleepy","bored"],"explanation":"feel calm 感到平静。"},{"q":"5","answer":"C","options":["sell","build","reduce","invite"],"explanation":"reduce stress 减轻压力。"},{"q":"6","answer":"D","options":["school","lunch","home","once"],"explanation":"at once 立刻。"},{"q":"7","answer":"A","options":["clear","dark","heavy","loud"],"explanation":"mind feels clear 头脑清醒。"},{"q":"8","answer":"B","options":["sleep","focus","shout","argue"],"explanation":"focus on my homework 专注作业。"},{"q":"9","answer":"C","options":["loudly","rarely","deeply","hardly"],"explanation":"sleep deeply 睡得沉。"},{"q":"10","answer":"D","options":["noise","price","ticket","courage"],"explanation":"the courage to face them 面对的勇气。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'A Breathing Exercise', 'Here is a simple breathing exercise you can (1)____ whenever you feel nervous. First, sit up straight and gently close your (2)____. Breathe in slowly through your nose and (3)____ the air for a few seconds. Then let it out softly through your (4)____. As you do this, try to (5)____ only on the sound of your own breath. If a worried thought comes, just let it (6)____ and quietly return to your breathing. After about five (7)____, your heartbeat will slow down and your whole body will feel (8)____. The best part is that no one around you will even (9)____. You can use this quiet trick before a test or any time you need to feel (10)____.', 119, 2, '[{"q":"1","answer":"A","options":["try","sell","throw","buy"],"explanation":"you can try 你可以试试。"},{"q":"2","answer":"B","options":["books","eyes","doors","shoes"],"explanation":"close your eyes 闭上眼睛。"},{"q":"3","answer":"C","options":["sell","drop","hold","throw"],"explanation":"hold the air 屏住气。"},{"q":"4","answer":"D","options":["window","pocket","garden","mouth"],"explanation":"through your mouth 用嘴呼出。"},{"q":"5","answer":"A","options":["focus","spend","argue","shout"],"explanation":"focus on the sound 专注于声音。"},{"q":"6","answer":"B","options":["grow","go","shout","cook"],"explanation":"let it go 让它过去。"},{"q":"7","answer":"C","options":["metres","coins","minutes","songs"],"explanation":"five minutes 五分钟。"},{"q":"8","answer":"D","options":["angry","hungry","noisy","relaxed"],"explanation":"feel relaxed 感到放松。"},{"q":"9","answer":"A","options":["notice","sell","cook","paint"],"explanation":"no one will notice 没人会察觉。"},{"q":"10","answer":"B","options":["afraid","calm","bored","angry"],"explanation":"feel calm 感到平静。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'A Counsellor''s Advice', 'When Tom could not stop (1)____ about everything, he decided to visit the school (2)____. She listened carefully and told him that his feelings were quite (3)____. Many students, she said, feel the same (4)____. Her first piece of advice was to (5)____ up his worries instead of hiding them away. The second was to keep a (6)____ life, with enough sleep, exercise and fun. She also taught him to (7)____ deeply whenever he felt panicky. Tom was surprised how much lighter he felt after just one (8)____. He realised that asking for help was a sign of (9)____, not weakness. Now, whenever a friend seems stressed, Tom (10)____ them to talk to someone they trust.', 116, 2, '[{"q":"1","answer":"C","options":["singing","cooking","worrying","shopping"],"explanation":"stop worrying 停止担忧。"},{"q":"2","answer":"D","options":["garden","ticket","machine","counsellor"],"explanation":"the school counsellor 学校的心理老师。"},{"q":"3","answer":"A","options":["normal","golden","silent","empty"],"explanation":"feelings were normal 感受是正常的。"},{"q":"4","answer":"B","options":["price","way","coin","noise"],"explanation":"feel the same way 有同样的感受。"},{"q":"5","answer":"C","options":["throw","sell","bring","wash"],"explanation":"bring up his worries 说出担忧。"},{"q":"6","answer":"D","options":["broken","frozen","golden","balanced"],"explanation":"a balanced life 平衡的生活。"},{"q":"7","answer":"A","options":["breathe","shout","jump","cook"],"explanation":"breathe deeply 深呼吸。"},{"q":"8","answer":"B","options":["coin","talk","garden","ticket"],"explanation":"after just one talk 只谈了一次。"},{"q":"9","answer":"C","options":["weather","traffic","strength","furniture"],"explanation":"a sign of strength 力量的表现。"},{"q":"10","answer":"D","options":["sells","throws","paints","advises"],"explanation":"advises them to talk 建议他们倾诉。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Before the Big Test', '上外版选择性必修第三册 U1 · dialogue', 3, 'Mia: You look really tired today, Sam. Are you all right?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 Good Stress and Bad Stress', '上外版选择性必修第三册 U1 · passage', 2, 'Not all stress is bad for you.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 A Visit to the Counsellor', '上外版选择性必修第三册 U1 · dialogue', 3, 'Counsellor: Come in, Leo. You said you wanted to talk about something?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 A Quick Way to Calm Down', '上外版选择性必修第三册 U1 · passage', 2, 'Here is a quick way to calm down when you feel panicky.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Planning a Balanced Weekend', '上外版选择性必修第三册 U1 · dialogue', 3, 'Emma: You''ve been studying all week, Jack. What are your plans for the weekend?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 Talking Helps', '上外版选择性必修第三册 U1 · passage', 2, 'When something is worrying you, do not keep it all inside.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Letter of Advice on Dealing with Stress(写一封应对压力的建议信)', 'A Letter of Advice to a Stressed Friend', '假设你叫李华。你的好友 Alan 最近因为学习和成绩压力很大,常常失眠、注意力不集中。请用英语写一封约 110-130 词的建议信,内容包括:① 表达你对他处境的理解与关心;② 给出一两条切实可行的应对压力的方法(如规律作息、运动、向人倾诉、深呼吸);③ 以鼓励的话结尾。注意书信格式、语气友好,不要批评。试着用本单元的不定式作主语/表语(如 To have a balanced life is …)。', 'Suppose you are Li Hua. Your good friend Alan is under great stress because of his studies and grades, and he often cannot sleep or focus. Write a letter of advice (about 110-130 words) including: 1) understanding and care for his situation; 2) one or two practical ways to deal with stress (e.g. a regular routine, exercise, talking to someone, deep breathing); 3) an encouraging ending. Keep a friendly tone and try to use infinitives as subjects/predicatives.', '["表达理解与关心(I''m sorry to hear that … / I know how hard it can be …)","给出可行建议(To have a balanced life is … / One thing you could try is …)","鼓励结尾(Don''t worry — things will get better!)","书信格式、语气友好、不定式作主语/表语运用得当"]'::jsonb, 70, 100, 'Dear Alan,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U1', '{"title":"不定式作主语和表语·速查","intro":"句子的主语或表语位置若要表达''做某事'',用不定式 to do。主语位置不能放有限动词;为求句子平衡,常用 it 作形式主语,把真正主语不定式放到句尾。","table":{"headers":["用法","结构 / 例句"],"rows":[["不定式作主语","To do … + is/takes …:To have a balanced life is the best way to fight stress."],["it 形式主语","It is + adj./n. + to do …:It is important to stay calm before a test."],["不定式作表语","主语 + be + to do …:My plan is to do some volunteer work."],["对比 -ing","不定式偏''具体/将来意图'',-ing 偏''泛指/习惯'':My favourite pastime is reading."]]},"specialRules":[{"rule":"主语位置不能用有限动词,用 To do(动词原形)","mark":"To have … √ / Have … × / Has … ×"},{"rule":"形式主语只能用 it,不能用 there/that/this","mark":"It is hard to … √ / There is hard to … ×"},{"rule":"be 后表语用 to do,说明或等同主语","mark":"The best way is to breathe slowly."},{"rule":"不定式作主语/表语,动词要用原形,不写 to doing","mark":"to have √ / to having ×"}],"why":["不定式 to do 本身相当于一个名词性成分,可以充当主语或表语;有限动词带时态,只能作谓语,所以不能放在主语位置。用 it 作形式主语是为了避免句子''头重脚轻'',让结构更平衡。"],"gaokaoPoints":["语法填空/选词:主语或 be 后空格,提示词是动词 → 多半填 to do。","It is + 形容词 + to do 是高频写作句型(important/necessary/hard/wise…)。","辨析不定式与动名词作主语/表语的细微差别(意图/将来 vs 泛指/习惯)。"],"examVsReal":[{"exam":"To get up early is good for health.（考试/书面、谚语体)","real":"It''s good to get up early. / Getting up early is good.","note":"考试爱考句首不定式;日常口语更常用 it 形式主语或动名词"},{"exam":"My plan is to travel this summer.（表语不定式)","real":"I''m planning to travel this summer.","note":"书面常用''be + to do''表语;口语常直接用动词 plan to do"}]}'::jsonb, 'sufe');
